-- 미들웨어 세트 126. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set126.sql, 05_display_order.sql, 06_units.sql, 08_set_icons.sql. docs/specs/spec_foundations_ladder.md
INSERT INTO unit (id, category, title, display_order) SELECT 20, '미들웨어', '데이터베이스', 40 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM unit WHERE id = 20);
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 126, 'DB 기초 1 (실습): 직접 쳐 보며 구경하기', 'MariaDB 에 접속해 데이터베이스와 테이블을 직접 구경해 봅니다. 데이터베이스·테이블 목록 저장, DESC 로 구조 읽기, SELECT 와 LIMIT, 필요한 열 고르기, 별명(AS), mariadb -N 으로 값만 뽑기, 현재 데이터베이스 확인을 작은 실습으로 다룹니다.', 'linux-db', '미들웨어'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 126);
UPDATE quest_set SET display_order = 539, unit_id = (SELECT id FROM unit WHERE id = 20), icon = '🔍' WHERE id = 126;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 1, '데이터베이스 목록 저장하기', '서버에 있는 데이터베이스 **목록**을 `/tmp/dbs.txt` 에 저장하세요. `shop` 이 보여야 합니다.', '`mariadb -e ''SQL문''` 으로 터미널에서 바로 SQL 을 실행할 수 있어요. 결과는 `>` 로 파일에 저장합니다.', 'mariadb -e ''SHOW DATABASES;'' > /tmp/dbs.txt
cat /tmp/dbs.txt

# mariadb -e ''SQL'' 은 접속해서 문장 하나를 실행하고 나온다. 스크립트에서 자주 쓴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/dbs.txt ] ) && ( grep -qx shop /tmp/dbs.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/dbs.txt ]"]}, {"label": "shop 이 목록에 있다", "cmd": ["sh", "-c", "grep -qx shop /tmp/dbs.txt"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 2, 'shop 안의 테이블 목록', '`shop` 데이터베이스 안의 **테이블 목록**을 `/tmp/tables.txt` 에 저장하세요. `customers` 와 `orders` 가 보여야 합니다.', '데이터베이스를 지정하려면 `mariadb shop -e ''...''` 처럼 이름을 먼저 씁니다.', 'mariadb shop -e ''SHOW TABLES;'' > /tmp/tables.txt
cat /tmp/tables.txt

# mariadb 데이터베이스이름 -e ''SQL'' : USE 를 따로 안 써도 그 DB 에서 실행된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( grep -qx customers /tmp/tables.txt ) && ( grep -qx orders /tmp/tables.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "customers 가 있다", "cmd": ["sh", "-c", "grep -qx customers /tmp/tables.txt"]}, {"label": "orders 가 있다", "cmd": ["sh", "-c", "grep -qx orders /tmp/tables.txt"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 3, 'customers 의 구조 보기', '`customers` 테이블의 **컬럼 구조**를 `/tmp/desc.txt` 에 저장하세요. `email` 컬럼이 보여야 합니다.', '구조를 보는 명령은 `DESC 테이블;` 이에요.', 'mariadb shop -e ''DESC customers;'' > /tmp/desc.txt
cat /tmp/desc.txt

# Field(컬럼), Type(타입), Null(NULL 허용), Key(PRI=기본키)를 읽는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/desc.txt ] ) && ( grep -q \\"^email\\" /tmp/desc.txt ) && ( grep -q \\"^id.*PRI\\" /tmp/desc.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/desc.txt ]"]}, {"label": "email 컬럼이 보인다", "cmd": ["sh", "-c", "grep -q \\"^email\\" /tmp/desc.txt"]}, {"label": "id 가 기본 키(PRI)이다", "cmd": ["sh", "-c", "grep -q \\"^id.*PRI\\" /tmp/desc.txt"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 4, '처음 3명만 보기', '`customers` 의 **모든 열, 처음 3행**을 `/tmp/first3.txt` 에 저장하세요. (제목 줄 1개 + 데이터 3줄이 됩니다)', '`SELECT * FROM customers LIMIT 3;`', 'mariadb shop -e ''SELECT * FROM customers LIMIT 3;'' > /tmp/first3.txt
cat /tmp/first3.txt

# 결과의 첫 줄은 컬럼 이름(제목)이다. LIMIT 3 이라 데이터는 3행이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/first3.txt)\\" -eq 4 ] ) && ( head -n 1 /tmp/first3.txt | grep -q city )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "4줄이다 (제목 1 + 데이터 3)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/first3.txt)\\" -eq 4 ]"]}, {"label": "제목에 city 가 있다", "cmd": ["sh", "-c", "head -n 1 /tmp/first3.txt | grep -q city"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 5, '이름과 이메일만 보기', '`customers` 에서 **이름(`name`)과 이메일(`email`) 열만** 모든 행을 `/tmp/ne.txt` 에 저장하세요. `city` 열은 없어야 합니다.', '열 이름을 쉼표로 이어 적어요: `SELECT name, email FROM ...`', 'mariadb shop -e ''SELECT name, email FROM customers;'' > /tmp/ne.txt
cat /tmp/ne.txt

# 필요한 열만 고르면 결과가 읽기 쉽고 가져오는 양도 줄어든다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(head -n 1 /tmp/ne.txt | tr \\"\\\\t\\" ,)\\" = \\"name,email\\" ] ) && ( [ \\"$(wc -l < /tmp/ne.txt)\\" -eq 6 ] ) && ( ! grep -q Seoul /tmp/ne.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목이 name 과 email 이다", "cmd": ["sh", "-c", "[ \\"$(head -n 1 /tmp/ne.txt | tr \\"\\\\t\\" ,)\\" = \\"name,email\\" ]"]}, {"label": "데이터가 5행이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/ne.txt)\\" -eq 6 ]"]}, {"label": "city 열이 없다", "cmd": ["sh", "-c", "! grep -q Seoul /tmp/ne.txt"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 6, '결과 열에 별명 붙이기', '`name` 열을 **`customer_name`** 이라는 별명으로 바꿔, 모든 행을 `/tmp/alias.txt` 에 저장하세요. (제목 줄이 `customer_name` 이 됩니다)', '`SELECT name AS customer_name FROM customers;`', 'mariadb shop -e ''SELECT name AS customer_name FROM customers;'' > /tmp/alias.txt
cat /tmp/alias.txt

# AS 는 결과에서 보이는 이름만 바꾼다. 테이블 컬럼 이름은 그대로다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(head -n 1 /tmp/alias.txt)\\" = customer_name ] ) && ( [ \\"$(wc -l < /tmp/alias.txt)\\" -eq 6 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목이 customer_name 이다", "cmd": ["sh", "-c", "[ \\"$(head -n 1 /tmp/alias.txt)\\" = customer_name ]"]}, {"label": "데이터가 5행이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/alias.txt)\\" -eq 6 ]"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 7, '제목 줄 없이 값만 뽑기', '`customers` 의 이름 **2개만**, **제목 줄 없이** 값만 `/tmp/plain.txt` 에 저장하세요. (스크립트에서 값을 이어 쓸 때 편합니다)', '`mariadb` 에 제목 줄을 빼는 옵션 `-N`(skip-column-names)이 있어요.', 'mariadb -N shop -e ''SELECT name FROM customers LIMIT 2;'' > /tmp/plain.txt
cat /tmp/plain.txt

# -N 은 제목 줄을 뺀다. 결과를 다른 명령으로 넘기거나 변수에 담을 때 쓴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/plain.txt)\\" -eq 2 ] ) && ( ! grep -qx name /tmp/plain.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/plain.txt)\\" -eq 2 ]"]}, {"label": "제목(name)이 없다", "cmd": ["sh", "-c", "! grep -qx name /tmp/plain.txt"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 126, 8, '지금 선택한 데이터베이스 확인하기', '`shop` 을 선택한 상태에서 **현재 데이터베이스 이름**을 보는 SQL 을 실행해 값만(제목 줄 없이) `/tmp/curdb.txt` 에 저장하세요.', '`SELECT DATABASE();` 를 `-N` 옵션과 함께 쓰세요.', 'mariadb -N shop -e ''SELECT DATABASE();'' > /tmp/curdb.txt
cat /tmp/curdb.txt

# 운영 서버에서 데이터를 바꾸기 전에 어느 DB 인지 확인하는 습관', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, email VARCHAR(50), city VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\",\\"kim@example.com\\",\\"Seoul\\"),(2,\\"lee\\",\\"lee@example.com\\",\\"Busan\\"),(3,\\"park\\",\\"park@example.com\\",\\"Seoul\\"),(4,\\"choi\\",\\"choi@example.com\\",\\"Daegu\\"),(5,\\"jung\\",\\"jung@example.com\\",\\"Busan\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, amount INT); INSERT INTO orders VALUES (1,1,12000),(2,1,5000),(3,3,30000);''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ \\"$(cat /tmp/curdb.txt)\\" = shop ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "값이 shop 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/curdb.txt)\\" = shop ]"]}]', '[{"title": "MariaDB 기본 SQL 문장", "url": "https://mariadb.com/kb/en/basic-sql-statements/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 126 AND order_index = 8);
